#include "../Source/InteractionMath.h"
#include "../Source/InteractionData.h"
#include <iostream>
int main(){int failures=0;double worst=0;const int rates[]{44100,48000,96000,192000};for(int r=0;r<4;++r){int local=0;for(int hf=0;hf<7;++hf)for(int hb=0;hb<5;++hb)for(int bw=0;bw<3;++bw)for(int af=0;af<3;++af)for(int ha=0;ha<5;++ha){double p[12];auto* v=EQPInteractions::rates[r].high[hf][hb][bw][af][ha];for(int i=0;i<12;++i)p[i]=v[i];double sos[3][5];if(!EQPInteractionMath::toSections(p,rates[r],sos)){++failures;++local;continue;}for(int k=0;k<32;++k){double f=20*std::pow(1000.,k/31.);auto w=EQPInteractionMath::Complex(0,2*rates[r]*std::tan(3.141592653589793*f/rates[r])/6283.185307179586);auto z=std::exp(EQPInteractionMath::Complex(0,-2*3.141592653589793*f/rates[r]));EQPInteractionMath::Complex n=p[5],d=p[11],h=1;for(int i=4;i>=0;--i){n=n*w+p[i];d=d*w+p[i+6];}for(auto& c:sos)h*=(c[0]+c[1]*z+c[2]*z*z)/(1.+c[3]*z+c[4]*z*z);double error=std::abs(h/(n/d)-1.);worst=std::max(worst,error);if(error>1e-5){++failures;++local;break;}}}std::cout<<rates[r]<<" failures="<<local<<" max relative error="<<worst<<"\n";}return failures?1:0;}
